 if(t){$('targeting').onchange=()=>{t.targetMode=$('targeting').value;};$('sellTower').onclick=()=>{if(result(game.sell(p,t.id))){selected=null;renderAll();}};if($('castTower'))$('castTower').onclick=()=>result(game.cast(p,t.id));if($('moveTower'))$('moveTower').onclick=()=>{moving=t.id;notify('Click walkable ground to move the golem.');};}
