function frame(now){const elapsed=Math.min((now-last)/1000,.1);last=now;let remaining=elapsed*game.speed;if(!$('setup').open&&!$('help').open){while(remaining>0){const dt=Math.min(remaining,.05);game.step(dt);remaining-=dt;}codeClock+=elapsed*game.speed;if(game.player.codeActive&&!game.paused&&!game.finished&&codeClock>=.25){codeClock=0;runCode('combat',false);}}
 draw();for(const e of game.events.splice(0)){audio.play(e);if(e.type==='unlock')notify(e.element?`${title(e.element)} unlocked.`:'Pure Essence earned.');}if(now-lastUI>200){updateHUD();lastUI=now;}if(now-lastSave>5000){saveGame();lastSave=now;}requestAnimationFrame(frame);}
function stopWorker(){workerGeneration++;if(worker)worker.terminate();worker=null;clearTimeout(workerTimer);}
function runCode(mode,announce=true){if(worker)return;const p=game.player,code=scripts[mode],generation=workerGeneration;const w=new Worker('runner.js');worker=w;workerTimer=setTimeout(()=>{if(worker!==w)return;stopWorker();p.codeActive=false;game.log('Script stopped after 500ms. Check for an infinite loop.');notify('Script timed out; built-in targeting restored.',true);if(tab==='code')renderPanel();},500);w.onmessage=({data:r})=>{if(generation!==workerGeneration)return;clearTimeout(workerTimer);w.terminate();worker=null;if(r.error){p.codeActive=false;game.log('Code error: '+r.error);notify(r.error,true);if(tab==='code')renderPanel();return;}if(mode==='combat')p.codeActive=true;for(const a of r.actions){let response;if(a.type==='attack'&&mode==='combat')game.attack(p,a.id,a.enemy);else if(a.type==='cast')response=game.cast(p,a.id);else if(mode==='build'){if(a.type==='build')response=game.build(p,a.tower,a.x,a.y);if(a.type==='upgrade'){const def=game.defs[a.tower]||data.towers.find(t=>t.name===a.tower);response=game.upgrade(p,a.id,def?.id||a.tower);}if(a.type==='sell')response=game.sell(p,a.id);if(a.type==='summon')response=game.summon(p,a.element);if(a.type==='interest')response=game.interestUpgrade(p);}if(response&&!response.ok&&announce)game.log(response.error);}for(const line of r.logs)game.log('› '+line);if(announce){notify(mode==='combat'?'Combat script applied. Your code controls targeting.':'Build script executed.');renderAll();}};w.onerror=e=>{stopWorker();p.codeActive=false;game.log('Worker error: '+e.message);notify('Code runner error. Built-in targeting restored.',true);};w.postMessage({code,state:game.snapshot(p)});}
function saveEditor(){try{localStorage.setItem('etd-editor',JSON.stringify(scripts));}catch{}}
function loadEditor(){try{const v=JSON.parse(localStorage.getItem('etd-editor'));if(v&&typeof v.build==='string'&&typeof v.combat==='string')scripts=v;}catch{}}
function serialize(){const keys=['options','seed','seq','time','wave','nextIn','spawning','roster','ronaldStage','ronaldInitialized','finished','ending','sharedPicks','autoplay','logs'];const state=Object.fromEntries(keys.map(k=>[k,game[k]]));state.banned=[...game.banned];state.clearedWaves=[...game.clearedWaves];state.players=game.players.map(p=>({...p,clears:[...p.clears],siteCache:undefined,enemies:p.enemies.map(e=>({...e,dots:e.dots.map(d=>({...d,tower:d.tower?{id:d.tower.id}:null})),napalm:e.napalm.map(m=>({...m,tower:m.tower?{id:m.tower.id}:null}))}))}));return {schema:1,source:data.sourceSha256,state};}
function saveGame(){if(!game||game.time===0||$('setup').open)return;try{localStorage.setItem('etd-save',JSON.stringify(serialize()));savedAvailable=true;}catch{/* Storage may be unavailable in private browsing. */}}
function checkSave(){try{const s=JSON.parse(localStorage.getItem('etd-save'));savedAvailable=s?.schema===1&&s.source===data.sourceSha256&&!s.state.finished;}catch{}$('loadSave').hidden=!savedAvailable;}
function loadGame(){try{const s=JSON.parse(localStorage.getItem('etd-save'));if(s.schema!==1||s.source!==data.sourceSha256)throw Error('Saved run is from a different version.');stopWorker();game=new Engine(data,s.state.options);Object.assign(game,s.state);game.players.forEach(p=>{p.clears=new Set(p.clears);p.codeActive=false;for(const e of p.enemies){for(const d of [...e.dots,...e.napalm])d.tower=p.towers.find(t=>t.id===d.tower?.id)||null;}});game.banned=new Set(s.state.banned);game.clearedWaves=new Set(s.state.clearedWaves);game.paused=false;game.speed=1;game.effects=[];game.events=[];window.elementGame=game;background=null;placing=null;selected=null;librarySelection=null;uiSignature='';$('setup').close();audio.start();renderAll();notify('Saved run restored. Built-in targeting is active.');}catch(e){notify('Could not restore save: '+e.message,true);}}
function showHelp(content){$('helpContent').innerHTML=content;$('help').showModal();}
function showDraft(){const roots=n=>data.towers.filter(t=>Object.keys(t.requirements).length===n&&Object.values(t.requirements).every(v=>v===1));showHelp('<h2>Choose the forbidden branches</h2><p>Eliminate five dual-element and seven triple-element families for this solo draft. Their upgraded forms are eliminated too. Seeded choices are selected initially.</p><form id="draftForm">'+[2,3].map(n=>'<h3>'+ (n===2?'Dual towers — choose five':'Triple towers — choose seven')+'</h3><div class="draft-grid">'+roots(n).map(t=>'<label><input type="checkbox" name="bans" value="'+t.id+'" '+(game.banned.has(t.id)?'checked':'')+'> '+esc(t.name.replace(' Tower',''))+'</label>').join('')+'</div>').join('')+'<button class="primary wide">Confirm draft & begin</button></form>');$('draftForm').onsubmit=e=>{e.preventDefault();const ids=new FormData(e.target).getAll('bans');const dual=ids.filter(id=>Object.keys(game.defs[id].requirements).length===2).length,triple=ids.length-dual;if(dual!==5||triple!==7){notify('Choose exactly five dual and seven triple families.',true);return;}game.setDraft(ids);game.log('Solo draft confirmed: five dual and seven triple branches eliminated.');$('help').close();renderAll();};}
function showAPI(){showHelp('<h2>JavaScript API</h2><p>Build code runs once. Combat code runs every 250ms in a separate worker. Scripts get a state snapshot; the game validates all actions. Long-running scripts stop after 500ms.</p><pre>build("Arrow", 1); // tower name, numbered site\nbuild("Fire", x, y); // world coordinates\nupgrade(towers[0].id, "h01U");\nsell(towers[0].id);\nsummon("water");\ninterest(); // spend one lumber for +1%\nattack(tower.id, enemy.id);\ncast(tower.id);\nlog(gold);</pre><p>Available variables: <code>gold, lumber, lives, wave, elements, towers, enemies, sites</code>. Use <code>distance(a, b)</code> for range checks. Find upgrade rawcodes in the Library. Building respects element requirements, costs, and placement.</p><p>Applying a combat script gives it full targeting control. Choose “Auto target” to restore built-in targeting. Scripts are local learning tools; do not paste secrets into them.</p>');}
$('setupForm').onsubmit=e=>{e.preventDefault();const form=new FormData(e.target);stopWorker();game=new Engine(data,{difficulty:+form.get('difficulty'),selection:form.get('selection'),length:form.get('length'),chaos:form.has('chaos'),extreme:form.has('extreme'),seed:+form.get('seed')||430});window.elementGame=game;selected=null;placing=null;librarySelection=null;moving=null;background=null;uiSignature='';audio.start();audio.setMusic(form.has('music'));$('setup').close();renderAll();if(game.options.selection==='DP')showDraft();try{localStorage.removeItem('etd-save');}catch{}notify('Start with Arrow towers. Earn your first elemental pick after wave 5.');};
$('resume').onclick=()=>$('setup').close();$('loadSave').onclick=loadGame;$('menu').onclick=()=>{saveGame();checkSave();$('setup').showModal();};$('again').onclick=()=>{checkSave();$('setup').showModal();};$('sound').onclick=()=>{audio.start();audio.enabled=!audio.enabled;$('sound').textContent=audio.enabled?'♪ Sound on':'♪ Muted';};$('send').onclick=()=>{audio.start();result(game.startWave());};$('pause').onclick=()=>{game.paused=!game.paused;updateHUD();};$('speed').onclick=()=>{game.speed=game.speed===1?2:game.speed===2?4:1;updateHUD();};$('sites').onclick=()=>{showSites=!showSites;$('sites').style.borderColor=showSites?'#b6dd89':'';};$('clearLog').onclick=()=>{game.logs=[];updateHUD();};
$('guide').onclick=()=>showHelp('<h2>Defend the frontier</h2><ol><li><strong>Build a starter defense.</strong> Select Arrow or Cannon, then click green ground next to the road. You begin with 70 gold.</li><li><strong>Summon an element.</strong> Spend lumber in the Elements tab. Defeat the guardian to unlock Fire, Nature, Earth, Light, Darkness, or Water.</li><li><strong>Follow upgrade branches.</strong> Select a built tower. Amplified single-element towers combine into dual towers; dual towers branch into triple towers.</li><li><strong>Keep gold working.</strong> Interest pays every 15 seconds. Spend lumber to increase the rate, or save it for another element.</li><li><strong>Survive 60 waves.</strong> Leaks lose lives and return with their remaining health. After wave 60, survive the Ronald finale.</li></ol><p>Fire → Nature → Earth → Light → Darkness → Water → Fire. Attacks deal 2× against the next element, 0.5× against the previous, and 0.8× against Composite.</p><p>Space pauses, Escape cancels placement, and the speed button cycles 1×/2×/4×. Touch controls work the same way. Progress saves automatically in this browser.</p><p>Optional: use real JavaScript in the Code tab to build, upgrade, and target enemies.</p>');
$('fidelity').onclick=()=>showHelp('<h2>Recreation notes</h2><p>This game uses the uploaded Element TD Survivor 4.3b map’s tower names, recipes, costs, attack stats, enemy roster, HP tables, damage matrix, bosses, terrain/pathing grid, and economy formulas. Art and audio are newly created.</p><div class="warning"><strong>It is a close browser recreation, not a verified exact port.</strong><p>Warcraft native pathfinding/collision, projectile geometry, spell timing, buff behavior, and several complex abilities are approximated. Draft uses solo elimination choices rather than multiplayer voting. Only single-player modes are included.</p></div><p>All 134 defense records are inspectable in the Library. See the repository’s FIDELITY.md for implemented mechanics and known differences. Your saved game and code stay in your browser.</p>');
document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$(b.dataset.close).close());document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;document.querySelectorAll('[data-tab]').forEach(v=>v.classList.toggle('active',v===b));if(tab==='code')showSites=true;renderPanel();});
canvas.onpointermove=e=>{if(transform)hover=worldFromPointer(e);};canvas.onpointerleave=()=>hover=null;canvas.onclick=e=>{if(!transform||game.finished)return;audio.start();const point=worldFromPointer(e);if(moving){if(result(game.moveGolem(game.player,moving,point.x,point.y)))moving=null;return;}if(placing){result(game.build(game.player,placing,point.x,point.y));return;}const nearest=game.player.towers.filter(t=>distance(t,point)<68).sort((a,b)=>distance(a,point)-distance(b,point))[0];selected=nearest?.id||null;librarySelection=null;renderInspector();};document.onkeydown=e=>{if(['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)||$('setup').open||$('help').open)return;if(e.code==='Space'){e.preventDefault();game.paused=!game.paused;updateHUD();}if(e.key==='Escape'){placing=null;moving=null;selected=null;renderAll();}};window.addEventListener('pagehide',saveGame);
$('cycle').innerHTML=ELEMENTS.map((e,i)=>`<span class="cycle-item"><b style="color:${COLORS[e]}">${ICONS[e]}</b>${title(e)}</span>${i<5?'<span class="cycle-arrow">→</span>':''}`).join('');
